import {crops} from './engine.mjs';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const photoAlt={rice:'Mature green rice panicles in a paddy field',wheat:'Golden wheat ears growing under a blue sky',millet:'Pearl millet seed heads growing in rows',chickpea:'Chickpea pods showing the seeds inside',maize:'A maize cob in its green husk on the plant',sorghum:'A sorghum plant and flowering panicle against blue sky',mung:'A close-up of harvested green mung beans'};
export function cropPhoto(key,cls=''){return `<img class="crop-photo ${cls}" src="assets/crops/${key}.jpg" alt="${photoAlt[key]}" loading="lazy" decoding="async" width="960" height="720">`}
export function rotationPhotos(pair){return `<div class="rotation-photos">${pair.map((key,i)=>`<button class="rotation-photo" data-action="crop-photo" data-crop="${key}" aria-label="View ${crops[key].name} photo and crop details">${cropPhoto(key)}<span><small>SEASON ${i+1}</small><b>${crops[key].name}</b></span></button>`).join('')}</div>`}
export function cropGallery(){return `<section class="crop-gallery"><div class="gallery-heading"><div><div class="eyebrow">MEET THE CROPS</div><h2>Real crops. More possibilities.</h2><p>Look closer at the plants behind your next rotation.</p></div><button class="text-button" data-action="photo-credits">Photo credits ↗</button></div><div class="crop-gallery-track">${['rice','wheat','millet','chickpea','maize','sorghum','mung'].map(key=>`<button class="crop-gallery-card" data-action="crop-photo" data-crop="${key}">${cropPhoto(key)}<span class="crop-gallery-label"><small>${crops[key].legume?'PULSE':'CEREAL'}</small><b>${crops[key].name}</b><span aria-hidden="true">↗</span></span></button>`).join('')}</div><p class="photo-note">Reference photography · not imagery of your field · <button class="text-button" data-action="photo-credits">Sources & licenses</button></p></section>`}
export function photoCreditsHTML(credits){return `<div class="dialog-heading"><div><div class="eyebrow">THE PEOPLE BEHIND THE PHOTOS</div><h2>Crop photography credits</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">×</button></div><p class="muted">Selected from Wikimedia Commons. Each photograph keeps its original license. Photos are reference illustrations of crops, not evidence about a selected field.</p><div class="credit-list">${Object.entries(credits).map(([key,p])=>`<article>${cropPhoto(key)}<div><h3>${crops[key].name}</h3><p>${escape(p.author)}</p><a href="${escape(p.page)}" target="_blank" rel="noopener">Original photograph ↗</a> · ${p.license_url?`<a href="${escape(p.license_url)}" target="_blank" rel="noopener">${escape(p.license)}</a>`:escape(p.license)}<small>${escape(p.changes)}</small></div></article>`).join('')}</div>`}
